import android.app.*;import android.os.*;import android.graphics.Color;import android.view.*;import android.widget.*;
public class MainActivity extends Activity{LinearLayout l; TextView state; public void onCreate(Bundle b){super.onCreate(b);l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setGravity(Gravity.CENTER);l.setPadding(28,28,28,28);l.setBackgroundColor(Color.rgb(8,8,16));add("8-Bit Ism",28);add("fme-8bit-ism-save-v1",13);button("NEW GAME");button("INSERT COIN");button("Directional pad • A / B / GB controls");state=add("READY",18);setContentView(l);}TextView add(String s,int z){TextView v=new TextView(this);v.setText(s);v.setTextColor(Color.WHITE);v.setTextSize(z);v.setGravity(Gravity.CENTER);v.setPadding(12,18,12,18);l.addView(v);return v;}void button(String s){Button x=new Button(this);x.setText(s);x.setOnClickListener(v->state.setText(s+" ✓"));l.addView(x);}}
